ALTER TABLE `User` MODIFY `email` VARCHAR(191) NULL, MODIFY `passwordHash` VARCHAR(191) NULL, ADD COLUMN `phone` VARCHAR(191) NULL, ADD COLUMN `phoneVerifiedAt` DATETIME(3) NULL, ADD UNIQUE INDEX `User_phone_key`(`phone`);
ALTER TABLE `Session` ADD COLUMN `deviceId` VARCHAR(191) NULL;
CREATE TABLE `OtpChallenge` (`id` VARCHAR(191) NOT NULL,`phone` VARCHAR(191) NOT NULL,`deviceLabel` VARCHAR(191) NOT NULL,`state` VARCHAR(191) NOT NULL DEFAULT 'STARTING',`providerSid` VARCHAR(191) NULL,`attempts` INTEGER NOT NULL DEFAULT 0,`expiresAt` DATETIME(3) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(`id`),INDEX `OtpChallenge_phone_createdAt_idx`(`phone`,`createdAt`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `DeviceSession` (`id` VARCHAR(191) NOT NULL,`userId` VARCHAR(191) NOT NULL,`tokenHash` VARCHAR(191) NOT NULL,`label` VARCHAR(191) NOT NULL,`expiresAt` DATETIME(3) NOT NULL,`revokedAt` DATETIME(3) NULL,`lastUsedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(`id`),UNIQUE INDEX `DeviceSession_tokenHash_key`(`tokenHash`),INDEX `DeviceSession_userId_revokedAt_idx`(`userId`,`revokedAt`),CONSTRAINT `DeviceSession_userId_fkey` FOREIGN KEY(`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
